<style>
.galit-gloss{--g:#74a42e;--gd:#438223;--gl:#f1f7e8;margin:2.5rem 0;font-family:Assistant,'Heebo',Arial,sans-serif}
.galit-gloss *{box-sizing:border-box}
.galit-gloss__head{margin-bottom:1.25rem}
.galit-gloss__head h2{margin:0 0 .35rem;font-size:1.65rem;font-weight:800;color:#25301c;line-height:1.25}
.galit-gloss__head h2::after{content:"";display:block;width:3rem;height:4px;background:var(--g);border-radius:2px;margin-top:.6rem}
.galit-gloss__sub{margin:.6rem 0 0;font-size:1rem;color:#5a6652;font-weight:600}
.galit-gloss__hint{margin:.5rem 0 0;font-size:.85rem;color:#7b8a72;display:flex;align-items:center;gap:.5rem;flex-wrap:wrap}
